widget.solution:
from itertools import combinations

def generate(B):
    """Every union of pieces of B (a list of frozensets), with the empty set."""
    out = set()
    for r in range(len(B) + 1):
        for pieces in combinations(B, r):
            out.add(frozenset().union(*pieces))
    return list(out)

def is_basis(X, B):
    """True if B covers X and each overlap point has a piece inside the overlap."""
    if frozenset().union(*B) != frozenset(X):
        return False
    for B1 in B:
        for B2 in B:
            for x in B1 & B2:
                if not any(x in B3 and B3 <= B1 & B2 for B3 in B):
                    return False
    return True

def subspace(tau, Y):
    """The subspace topology on Y."""
    Y = frozenset(Y)
    return list({U & Y for U in tau})
